CREATE TABLE authentication_guard (id integer PRIMARY KEY);
INSERT INTO authentication_guard(id) VALUES (1);
CREATE TABLE authentication_limit (bucket varchar(64) PRIMARY KEY, attempts integer NOT NULL, expires_at timestamp with time zone NOT NULL);
CREATE TABLE platform_mfa (user_id bigint PRIMARY KEY REFERENCES app_users(id), secret_ciphertext varchar(1024) NOT NULL, enabled boolean NOT NULL DEFAULT FALSE, last_step bigint NOT NULL DEFAULT -1, created_at timestamp with time zone NOT NULL);
CREATE TABLE security_audit (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, occurred_at timestamp with time zone NOT NULL, actor_id bigint, action varchar(60) NOT NULL, status integer NOT NULL);
CREATE INDEX security_audit_time ON security_audit(occurred_at);
CREATE TABLE platform_recovery_code (user_id bigint NOT NULL REFERENCES app_users(id), code_hash varchar(64) NOT NULL, PRIMARY KEY(user_id,code_hash));
